    "py": "Nǚ'ér què shì yì liǎn de yíhuò, fǎnwèn dào: “Nǐmen bú shì yě yǒu shíhou shuō, nǎge péngyou hǎo xiāngchǔ, nǎge péngyou hěn zìsī ma?”",
